    );
  }

  if (questionType === "TRUE_FALSE") {
    return (
      <fieldset className="content-stack">
        <legend>Choose true or false</legend>
        {[
          ["true", "True"],
          ["false", "False"]
        ].map(([optionValue, label]) => (
          <label className="ds-checkbox-field" key={optionValue}>
