      `UPDATE assessment_attempt_drafts
       SET text_value=$8,
           boolean_value=$9,
           revision=revision+1,
           latest_mutation_key=$10,
           latest_mutation_digest=$11,
           updated_at=$12
       WHERE attempt_id=$1
         AND form_id=$2
         AND form_item_id=$3
