export async function countRows(db, table, where = "TRUE", params = []) {
  const result = await db.query(`SELECT COUNT(*)::int AS count FROM ${table} WHERE ${where}`, params);
  return result.rows[0].count;
}

export class AssessmentAttemptService {
  constructor(private readonly database: DatabaseClient) {}

  async begin(
    principal: AuthorizationPrincipal,
    input: { caseId: string; catalogueVersionId: string },
    now = new Date()
  ): Promise<AssessmentAttemptView> {
    const caseId = input.caseId.trim();
    const catalogueVersionId = input.catalogueVersionId.trim();
    if (
      !CASE_ID_PATTERN.test(caseId) ||
      !CATALOGUE_VERSION_ID_PATTERN.test(catalogueVersionId)
    ) {
      throw new AssessmentAttemptInputError("Assessment selection reference is invalid.");
    }

    return this.database.transaction(async (database) => {
      await assertLiveWorker(database, principal, now);

      const caseResult = await database.query<OwnedCaseRow>(
        `SELECT case_id,order_id,tenant_id,worker_account_id,case_status
         FROM assurance_cases
         WHERE case_id=$1 AND worker_account_id=$2
         FOR UPDATE`,
        [caseId, principal.accountId]
      );
      const assuranceCase = caseResult.rows[0];
      if (!assuranceCase) throw new AssessmentAttemptAccessError();

      const repository = new AssessmentAttemptRepository(database);
      const existing = await repository.findByCaseCatalogueOwned(
        principal.accountId,
        caseId,
        catalogueVersionId
      );
      if (existing) {
        if (assuranceCase.case_status !== "Assessment in progress") {
          throw new AssessmentAttemptConflictError();
        }
        return view(repository, existing);
      }
      if (assuranceCase.case_status !== "Assessment pending") {
        throw new AssessmentAttemptAccessError();
      }

      const available = await new AssessmentCatalogueEligibilityService(database)
        .findAvailableForCase(principal, caseId, now);
      const selected = available.find(
        (entry) => entry.catalogueVersionId === catalogueVersionId
      );
      if (!selected) throw new AssessmentAttemptAccessError();

      const form = await new AssessmentFormGenerationService(database).generateForCase(
        principal,
        {
          caseId,
          blueprintVersionId: selected.blueprintVersionId
        },
        now
      );

      const alreadyForForm = await repository.findByForm(principal.accountId, form.formId);
      if (alreadyForForm) return view(repository, alreadyForForm);

      const created = await repository.insertAttempt({
        attemptId: createAssessmentAttemptId(),
        caseId,
        workerAccountId: principal.accountId,
        catalogueVersionId,
        blueprintVersionId: selected.blueprintVersionId,
        formId: form.formId,
        questionCount: form.questionCount,
        now: now.toISOString()
      });

      const transitioned = await database.query(
        `UPDATE assurance_cases
         SET case_status='Assessment in progress',
             owner_kind='worker',
             next_action='Complete the assessment for this Assurance Case.',
             assessment_reference=$3,
             updated_at=$4
         WHERE case_id=$1
           AND worker_account_id=$2
           AND case_status='Assessment pending'`,
        [caseId, principal.accountId, created.attemptId, now.toISOString()]
      );
      if (transitioned.affectedRows !== 1) {
        throw new AssessmentAttemptConflictError();
      }

      await new AssuranceOrderRepository(database).insertTimeline({
        eventId: createAssuranceTimelineEventId(),
        tenantId: assuranceCase.tenant_id,
        orderId: assuranceCase.order_id,
        caseId,
        eventType: "assessment_attempt_started",
        fromStatus: "Assessment pending",
        toStatus: "Assessment in progress",
        owner: "worker",
        nextAction: "Complete the assessment for this Assurance Case.",
        actorAccountId: principal.accountId,
        actorRole: principal.activeRole,
        now: now.toISOString()
      });

      await new DatabaseAuditRepository(Promise.resolve(database)).append(
        bindTrustedAuditActor(principal),
        {
          action: "assessment.attempt.started",
          outcome: "succeeded",
          target: { type: "resource", reference: created.attemptId },
          metadata: {
            caseId,
            catalogueVersionId,
            blueprintVersionId: created.blueprintVersionId,
            formId: created.formId,
            questionCount: created.questionCount
          }
        }
      );

      return view(repository, created);
    });
  }

  async getOwnedView(
    principal: AuthorizationPrincipal,
    attemptReference: string,
    now = new Date()
  ): Promise<AssessmentAttemptView> {
    const attemptId = normalizeAssessmentAttemptReference(attemptReference);
    return this.database.transaction(async (database) => {
      await assertLiveWorker(database, principal, now);
      const repository = new AssessmentAttemptRepository(database);
      const attempt = await repository.findOwned(principal.accountId, attemptId);
      if (!attempt) throw new AssessmentAttemptAccessError();
      return view(repository, attempt);
    });
  }

  async listOwnedInProgress(
    principal: AuthorizationPrincipal,
    now = new Date()
  ): Promise<readonly OwnedInProgressAssessmentAttempt[]> {
    return this.database.transaction(async (database) => {
      await assertLiveWorker(database, principal, now);
      return new AssessmentAttemptRepository(database).listOwnedInProgress(
        principal.accountId
      );
    });
  }

  async saveCurrentDraft(
    principal: AuthorizationPrincipal,
    input: {
      attemptId: string;
      position: number;
      questionVersionId: string;
      value: unknown;
      expectedRevision: number | null;
      mutationKey: string;
    },
    now = new Date()
  ): Promise<AssessmentAttemptDraftSnapshot> {
    const attemptId = normalizeAssessmentAttemptReference(input.attemptId);
    if (!Number.isSafeInteger(input.position) || input.position < 1) {
      throw new AssessmentAttemptInputError("Assessment position is invalid.");
    }
    const questionVersionId = input.questionVersionId.trim();
    if (!QUESTION_VERSION_ID_PATTERN.test(questionVersionId)) {
      throw new AssessmentAttemptInputError("Assessment question reference is invalid.");
    }
    const expectedRevision = normalizeDraftExpectedRevision(input.expectedRevision);
    const mutationKey = normalizeDraftMutationKey(input.mutationKey);

    return this.database.transaction(async (database) => {
      await assertLiveWorker(database, principal, now);
      const repository = new AssessmentAttemptRepository(database);
      const locked = await repository.lockOwned(principal.accountId, attemptId);
      if (!locked) throw new AssessmentAttemptAccessError();
      if (locked.status !== "IN_PROGRESS") {
        throw new AssessmentAttemptConflictError();
      }

      const item = await repository.loadCurrentPinnedItem(principal.accountId, attemptId);
      if (!item) {
        throw new AssessmentAttemptConflictError("The current assessment question is unavailable.");
      }
      if (
        input.position !== locked.currentPosition ||
        item.position !== locked.currentPosition ||
        questionVersionId !== item.questionVersionId
      ) {
        throw new AssessmentAttemptConflictError();
      }

      const committed = await repository.findCommittedAnswer(
        principal.accountId,
        attemptId,
        locked.currentPosition
      );
      if (committed) {
        throw new AssessmentAttemptConflictError();
      }

      const normalized = normalizeAssessmentDraft(
        item.questionType,
        input.value,
        item.options
      );
      const saved = await repository.saveCurrentDraftCompareAndSwap({
        attempt: locked,
        item,
        value: normalized,
        expectedRevision,
        mutationKey,
        now: now.toISOString()
      });
      if (saved.kind !== "saved") {
        throw new AssessmentAttemptConflictError();
      }
      return saved.draft;
    });
  }

  async submitCurrentAnswer(
    principal: AuthorizationPrincipal,
    input: {
      attemptId: string;
      position: number;
      questionVersionId: string;
      answer: unknown;
    },
    now = new Date()
  ): Promise<AssessmentAttemptView> {
    const attemptId = normalizeAssessmentAttemptReference(input.attemptId);
    if (!Number.isSafeInteger(input.position) || input.position < 1) {
      throw new AssessmentAttemptInputError("Assessment position is invalid.");
    }
    const questionVersionId = input.questionVersionId.trim();
    if (!QUESTION_VERSION_ID_PATTERN.test(questionVersionId)) {
      throw new AssessmentAttemptInputError("Assessment question reference is invalid.");
    }

    return this.database.transaction(async (database) => {
      await assertLiveWorker(database, principal, now);
      const repository = new AssessmentAttemptRepository(database);
      const locked = await repository.lockOwned(principal.accountId, attemptId);
      if (!locked) throw new AssessmentAttemptAccessError();

      const committed = await repository.findCommittedAnswer(
        principal.accountId,
        attemptId,
        input.position
      );
      if (committed) {
        if (committed.questionVersionId !== questionVersionId) {
          throw new AssessmentAttemptConflictError();
        }
        const replay = normalizeAssessmentAnswer(
          committed.questionType,
          input.answer,
          committed.options
        );
        if (!sameNormalizedAnswer(committed.value, replay)) {
          throw new AssessmentAttemptConflictError();
        }
        return view(repository, locked);
      }

      if (locked.status !== "IN_PROGRESS") {
        throw new AssessmentAttemptConflictError();
      }

      const item = await repository.loadCurrentPinnedItem(principal.accountId, attemptId);
      if (!item) {
        throw new AssessmentAttemptConflictError("The current assessment question is unavailable.");
      }
      if (
        input.position !== locked.currentPosition ||
        item.position !== locked.currentPosition ||
        questionVersionId !== item.questionVersionId
      ) {
        throw new AssessmentAttemptConflictError();
      }

      const normalized = normalizeAssessmentAnswer(
        item.questionType,
        input.answer,
        item.options
      );
      await repository.insertCommittedAnswer({
        answerId: createAssessmentAnswerId(),
        attempt: locked,
        item,
        value: normalized,
        now: now.toISOString()
      });
      await repository.deleteCurrentDraft(locked, item);

      if (locked.currentPosition < locked.questionCount) {
        const advanced = await repository.advancePosition(
          principal.accountId,
          attemptId,
          locked.currentPosition,
          now.toISOString()
        );
        if (!advanced) throw new AssessmentAttemptConflictError();
        return view(repository, advanced);
      }

      const submitted = await repository.markSubmitted(
        principal.accountId,
        attemptId,
        locked.currentPosition,
        now.toISOString()
      );
      if (!submitted) throw new AssessmentAttemptConflictError();

      const caseResult = await database.query<OwnedCaseRow>(
        `SELECT case_id,order_id,tenant_id,worker_account_id,case_status
         FROM assurance_cases
         WHERE case_id=$1 AND worker_account_id=$2
         LIMIT 1`,
        [submitted.caseId, principal.accountId]
      );
      const assuranceCase = caseResult.rows[0];
      if (!assuranceCase || assuranceCase.case_status !== "Assessment in progress") {
        throw new AssessmentAttemptConflictError();
      }

      await new AssuranceOrderRepository(database).insertTimeline({
        eventId: createAssuranceTimelineEventId(),
        tenantId: assuranceCase.tenant_id,
        orderId: assuranceCase.order_id,
        caseId: submitted.caseId,
        eventType: "assessment_attempt_submitted",
        fromStatus: "Assessment in progress",
        toStatus: "Assessment in progress",
        owner: "worker",
        nextAction: null,
        actorAccountId: principal.accountId,
        actorRole: principal.activeRole,
        now: now.toISOString()
      });

      await new DatabaseAuditRepository(Promise.resolve(database)).append(
        bindTrustedAuditActor(principal),
        {
          action: "assessment.attempt.submitted",
          outcome: "succeeded",
          target: { type: "resource", reference: submitted.attemptId },
          metadata: {
            caseId: submitted.caseId,
            catalogueVersionId: submitted.catalogueVersionId,
            blueprintVersionId: submitted.blueprintVersionId,
            formId: submitted.formId,
            position: submitted.currentPosition,
            questionCount: submitted.questionCount
          }
        }
      );

      return view(repository, submitted);
    });
  }
}

let service: AssessmentAttemptService | null = null;

export async function getAssessmentAttemptService(): Promise<AssessmentAttemptService> {
  service ??= new AssessmentAttemptService(await getDatabaseClient());
  return service;
}

"use server";

import { redirect } from "next/navigation";

import { AssessmentAttemptAnswerInputError } from "@/lib/assessment-attempt/assessment-attempt-domain";
import { AssessmentAttemptDraftInputError } from "@/lib/assessment-attempt/assessment-attempt-draft-domain";
import {
  AssessmentAttemptAccessError,
  AssessmentAttemptConflictError,
  AssessmentAttemptInputError,
  getAssessmentAttemptService
} from "@/lib/assessment-attempt/assessment-attempt-service";
import { requirePlatformPermission } from "@/lib/authorization/authorization-service";

export type AssessmentAnswerActionState = Readonly<{
  status: "idle" | "error" | "conflict";
  message: string;
}>;

export type AssessmentDraftConflictSnapshot = Readonly<{
  value: string | boolean | null;
  revision: number;
  updatedAt: string;
}>;

export type AssessmentDraftActionResult =
  | Readonly<{
      status: "saved";
      revision: number;
      updatedAt: string;
    }>
  | Readonly<{
      status: "conflict";
      message: string;
      serverDraft: AssessmentDraftConflictSnapshot | null;
    }>
  | Readonly<{
      status: "error";
      message: string;
    }>;

function state(
  status: AssessmentAnswerActionState["status"],
  message: string
): AssessmentAnswerActionState {
  return Object.freeze({ status, message });
}

function positiveInteger(value: string): number | null {
  if (!/^\d+$/.test(value.trim())) return null;
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) && parsed > 0 ? parsed : null;
}

function optionalPositiveInteger(value: string): number | null | undefined {
  const normalized = value.trim();
  if (!normalized) return null;
  if (!/^\d+$/.test(normalized)) return undefined;
  const parsed = Number(normalized);
  return Number.isSafeInteger(parsed) && parsed > 0 ? parsed : undefined;
}

export async function saveAssessmentDraftAction(
  formData: FormData
): Promise<AssessmentDraftActionResult> {
  const rawAttemptId = formData.get("attemptId");
  const rawPosition = formData.get("position");
  const rawQuestionVersionId = formData.get("questionVersionId");
  const rawDraftPayload = formData.get("draftPayload");
  const rawExpectedRevision = formData.get("expectedRevision");
  const rawClientGeneratedMutationKey = formData.get("clientGeneratedMutationKey");

  const attemptId = typeof rawAttemptId === "string" ? rawAttemptId.trim() : "";
  const position = positiveInteger(typeof rawPosition === "string" ? rawPosition : "");
  const questionVersionId =
    typeof rawQuestionVersionId === "string" ? rawQuestionVersionId.trim() : "";
  const draftPayload = typeof rawDraftPayload === "string" ? rawDraftPayload : "";
  const expectedRevision =
    typeof rawExpectedRevision === "string"
      ? optionalPositiveInteger(rawExpectedRevision)
      : undefined;
  const clientGeneratedMutationKey =
    typeof rawClientGeneratedMutationKey === "string"
      ? rawClientGeneratedMutationKey
      : "";

  if (
    !attemptId ||
    position === null ||
    !questionVersionId ||
    !draftPayload ||
    expectedRevision === undefined ||
    !clientGeneratedMutationKey
  ) {
    return Object.freeze({
      status: "error" as const,
      message: "This draft could not be saved. Reload the current question and try again."
    });
  }

  let draftValue: unknown;
  try {
    draftValue = JSON.parse(draftPayload) as unknown;
  } catch {
    return Object.freeze({
      status: "error" as const,
      message: "This draft could not be saved. Reload the current question and try again."
    });
  }

  try {
    const principal = await requirePlatformPermission({
      expectedRole: "worker",
      permission: "worker.assessments.read"
    });
    const service = await getAssessmentAttemptService();

    try {
      const saved = await service.saveCurrentDraft(principal, {
        attemptId,
        position,
        questionVersionId,
        value: draftValue,
        expectedRevision,
        mutationKey: clientGeneratedMutationKey
      });
      return Object.freeze({
        status: "saved" as const,
        revision: saved.revision,
        updatedAt: saved.updatedAt
      });
    } catch (error) {
      if (!(error instanceof AssessmentAttemptConflictError)) throw error;

      let serverDraft: AssessmentDraftConflictSnapshot | null = null;
      try {
        const current = await service.getOwnedView(principal, attemptId);
        if (
          current.currentQuestion !== null &&
          current.currentDraft !== null &&
          current.currentQuestion.position === position &&
          current.currentQuestion.questionVersionId === questionVersionId
        ) {
          serverDraft = Object.freeze({
            value: current.currentDraft.value,
            revision: current.currentDraft.revision,
            updatedAt: current.currentDraft.updatedAt
          });
        }
      } catch (readError) {
        if (
          !(readError instanceof AssessmentAttemptAccessError) &&
          !(readError instanceof AssessmentAttemptConflictError) &&
          !(readError instanceof AssessmentAttemptInputError)
        ) {
          throw readError;
        }
      }

      return Object.freeze({
        status: "conflict" as const,
        message: "This draft changed in another tab. Choose which version to keep.",
        serverDraft
      });
    }
  } catch (error) {
    if (
      error instanceof AssessmentAttemptDraftInputError ||
      error instanceof AssessmentAttemptInputError
    ) {
      return Object.freeze({
        status: "error" as const,
        message: "This draft could not be saved. Reload the current question and try again."
      });
    }
    if (error instanceof AssessmentAttemptAccessError) {
      return Object.freeze({
        status: "error" as const,
        message: "This assessment is no longer available in the current session."
      });
    }
    throw error;
  }
}

export async function submitAssessmentAnswerAction(
  _previousState: AssessmentAnswerActionState,
  formData: FormData
): Promise<AssessmentAnswerActionState> {
  const rawAttemptId = formData.get("attemptId");
  const rawPosition = formData.get("position");
  const rawQuestionVersionId = formData.get("questionVersionId");
  const rawAnswer = formData.get("answer");
  const attemptId = typeof rawAttemptId === "string" ? rawAttemptId.trim() : "";
  const position = positiveInteger(typeof rawPosition === "string" ? rawPosition : "");
  const questionVersionId =
    typeof rawQuestionVersionId === "string" ? rawQuestionVersionId.trim() : "";
  const encodedAnswer = typeof rawAnswer === "string" ? rawAnswer : "";

  if (!attemptId || position === null || !questionVersionId || !encodedAnswer) {
    return state("error", "This assessment question is stale. Reload it and try again.");
  }

  let answer: unknown;
  try {
    answer = JSON.parse(encodedAnswer) as unknown;
  } catch {
    return state("error", "Enter a valid answer before continuing.");
  }

  try {
    const principal = await requirePlatformPermission({
      expectedRole: "worker",
      permission: "worker.assessments.read"
    });
    await (
      await getAssessmentAttemptService()
    ).submitCurrentAnswer(
      principal,
      { attemptId, position, questionVersionId, answer }
    );
  } catch (error) {
    if (error instanceof AssessmentAttemptConflictError) {
      return state(
        "conflict",
        "This assessment changed in another request. Reload the current question before continuing."
      );
    }
    if (
      error instanceof AssessmentAttemptAnswerInputError ||
      error instanceof AssessmentAttemptInputError
    ) {
      return state("error", "Enter a valid answer before continuing.");
    }
    if (error instanceof AssessmentAttemptAccessError) {
      return state("error", "This assessment is no longer available in the current session.");
    }
    throw error;
  }

  redirect(`/worker/assessments/${attemptId}`);
}
"use client";

import { useRouter } from "next/navigation";
import { useActionState, useState } from "react";

import {
  submitAssessmentAnswerAction,
  type AssessmentAnswerActionState
} from "@/app/worker/(portal)/assessments/[attemptId]/actions";
import { Button } from "@/components/ui/button";
import { Alert } from "@/components/ui/feedback";
import { Field, Input, Textarea } from "@/components/ui/field";
import type { AssessmentAttemptClientView } from "@/lib/assessment-attempt/assessment-attempt-domain";
import { useAssessmentDraftAutosave } from "./use-assessment-draft-autosave";

const INITIAL_STATE: AssessmentAnswerActionState = Object.freeze({
  status: "idle",
  message: ""
});

function encodeAnswer(questionType: string, value: string): string {
  if (questionType === "TRUE_FALSE") {
    if (value === "true") return "true";
    if (value === "false") return "false";
    return JSON.stringify(value);
  }
  if (questionType === "INTEGER" || questionType === "DECIMAL") {
    const trimmed = value.trim();
    if (trimmed.length > 0) {
      const numeric = Number(trimmed);
      if (Number.isFinite(numeric)) return JSON.stringify(numeric);
    }
  }
  return JSON.stringify(value);
}

function AnswerControl({
  questionType,
  options,
  value,
  onChange
}: {
  questionType: NonNullable<AssessmentAttemptClientView["currentQuestion"]>["questionType"];
  options: readonly string[] | null;
  value: string;
  onChange: (value: string) => void;
}): React.JSX.Element {
  if (questionType === "MULTIPLE_CHOICE") {
    return (
      <fieldset className="content-stack">
        <legend>Choose one answer</legend>
        {(options ?? []).map((option) => (
          <label className="ds-checkbox-field" key={option}>
            <input
              type="radio"
              checked={value === option}
              onChange={() => onChange(option)}
            />
            <span>{option}</span>
          </label>
        ))}
      </fieldset>
    );
  }

  if (questionType === "TRUE_FALSE") {
    return (
      <fieldset className="content-stack">
        <legend>Choose true or false</legend>
        {[
          ["true", "True"],
          ["false", "False"]
        ].map(([optionValue, label]) => (
          <label className="ds-checkbox-field" key={optionValue}>
            <input
              type="radio"
              checked={value === optionValue}
              onChange={() => onChange(optionValue)}
            />
            <span>{label}</span>
          </label>
        ))}
      </fieldset>
    );
  }

  if (questionType === "SHORT_TEXT") {
    return (
      <Field htmlFor="assessment-short-answer" label="Your answer">
        <Input
          id="assessment-short-answer"
          type="text"
          value={value}
          maxLength={2000}
          onChange={(event) => onChange(event.currentTarget.value)}
          autoComplete="off"
        />
      </Field>
    );
  }

  if (questionType === "LONG_TEXT") {
    return (
      <Field htmlFor="assessment-long-answer" label="Your answer">
        <Textarea
          id="assessment-long-answer"
          value={value}
          maxLength={20000}
          rows={10}
          onChange={(event) => onChange(event.currentTarget.value)}
        />
      </Field>
    );
  }

  if (questionType === "INTEGER") {
    return (
      <Field htmlFor="assessment-integer-answer" label="Your answer">
        <Input
          id="assessment-integer-answer"
          type="text"
          value={value}
          onChange={(event) => onChange(event.currentTarget.value)}
          inputMode="numeric"
          autoComplete="off"
        />
      </Field>
    );
  }

  if (questionType === "DECIMAL") {
    return (
      <Field htmlFor="assessment-decimal-answer" label="Your answer">
        <Input
          id="assessment-decimal-answer"
          type="text"
          value={value}
          onChange={(event) => onChange(event.currentTarget.value)}
          inputMode="decimal"
          autoComplete="off"
        />
      </Field>
    );
  }

  return <Alert tone="danger">This question type is unavailable.</Alert>;
}

function ActiveAssessmentWorkspace({
  view,
  question
}: {
  view: AssessmentAttemptClientView;
  question: NonNullable<AssessmentAttemptClientView["currentQuestion"]>;
}): React.JSX.Element {
  const router = useRouter();
  const [exitPending, setExitPending] = useState(false);
  const [state, action, pending] = useActionState(
    submitAssessmentAnswerAction,
    INITIAL_STATE
  );
  const {
    value: answer,
    setValue: setAnswer,
    saveStatus,
    conflict,
    useSavedVersion,
    replaceSavedVersion,
    flushExactCurrentEdit,
    bestEffortCurrentEdit
  } = useAssessmentDraftAutosave({
    question,
    initialDraft: view.currentDraft
  });

  const handleSaveAndExit = async (): Promise<void> => {
    setExitPending(true);
    const saved = await flushExactCurrentEdit();
    if (saved) {
      router.push("/worker/available-assessments");
      return;
    }
    setExitPending(false);
  };

  const handleEmergencyExit = async (): Promise<void> => {
    await bestEffortCurrentEdit();
    router.push("/worker/available-assessments");
  };

  return (
    <section className="page-stack" aria-labelledby="assessment-heading">
      <div className="page-heading">
        <div>
          <p className="eyebrow">Candidate assessment</p>
          <h1 id="assessment-heading">Assessment</h1>
          <p>Question {question.position} of {question.questionCount}</p>
        </div>
      </div>

      <section className="panel page-section content-stack" aria-labelledby="current-question-heading">
        <div>
          <p className="eyebrow">{question.domainReference} · {question.difficulty}</p>
          <h2 id="current-question-heading">Question {question.position}</h2>
          <p>{question.prompt}</p>
        </div>

        <div role="status" aria-live="polite">
          {saveStatus}
        </div>

        {conflict ? (
          <Alert tone="warning">
            <div className="content-stack">
              <p>{conflict.message}</p>
              {conflict.serverDraft ? (
                <div className="button-row">
                  <Button type="button" variant="secondary" onClick={useSavedVersion}>
                    Use saved version
                  </Button>
                  <Button type="button" onClick={replaceSavedVersion}>
                    Replace saved version with this tab
                  </Button>
                </div>
              ) : (
                <p>Reload the current question before editing again.</p>
              )}
            </div>
          </Alert>
        ) : null}

        {state.message ? (
          <Alert tone={state.status === "conflict" ? "warning" : "danger"} role="status">
            {state.message}
          </Alert>
        ) : null}

        <form action={action} className="content-stack">
          <input type="hidden" name="attemptId" value={question.attemptId} />
          <input type="hidden" name="position" value={String(question.position)} />
          <input type="hidden" name="questionVersionId" value={question.questionVersionId} />
          <input type="hidden" name="answer" value={encodeAnswer(question.questionType, answer)} />

          <AnswerControl
            questionType={question.questionType}
            options={question.options}
            value={answer}
            onChange={setAnswer}
          />

          <Button type="submit" disabled={pending || exitPending}>
            {pending
              ? "Saving…"
              : question.position === question.questionCount
                ? "Submit assessment"
                : "Next"}
          </Button>
        </form>

        <div className="content-stack" aria-label="Assessment exit controls">
          <div className="button-row">
            <Button
              type="button"
              variant="secondary"
              disabled={exitPending}
              onClick={() => void handleSaveAndExit()}
            >
              {exitPending ? "Saving before exit…" : "Save and exit"}
            </Button>
            <Button
              type="button"
              variant="danger"
              onClick={() => void handleEmergencyExit()}
            >
              Emergency exit
            </Button>
          </div>
          <p className="muted-copy">
            Emergency exit does not submit or advance this assessment. Only the last server-confirmed Saved version is guaranteed recoverable.
          </p>
        </div>
      </section>
    </section>
  );
}

export function AssessmentWorkspace({
  view
}: {
  view: AssessmentAttemptClientView;
}): React.JSX.Element {
  if (view.submitted) {
    return (
      <section className="page-stack" aria-labelledby="assessment-heading">
        <div className="page-heading">
          <div>
            <p className="eyebrow">Assessment submitted</p>
            <h1 id="assessment-heading">Assessment</h1>
            <p>Your responses have been submitted. Results are not calculated in this assessment window.</p>
          </div>
        </div>
        <Alert tone="success" role="status">
          Submission received. You may leave this page safely.
        </Alert>
      </section>
    );
  }

  const question = view.currentQuestion;
  if (!question) {
    return (
      <section className="page-stack" aria-labelledby="assessment-heading">
        <h1 id="assessment-heading">Assessment</h1>
        <Alert tone="danger">The current question is unavailable.</Alert>
      </section>
    );
  }

  return (
    <ActiveAssessmentWorkspace
      key={`${question.attemptId}:${question.position}:${question.questionVersionId}`}
      view={view}
      question={question}
    />
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import {
  saveAssessmentDraftAction,
  type AssessmentDraftConflictSnapshot
} from "@/app/worker/(portal)/assessments/[attemptId]/actions";
import type {
  AssessmentAttemptClientDraft,
  AssessmentAttemptClientQuestion
} from "@/lib/assessment-attempt/assessment-attempt-domain";

type SaveRequest = Readonly<{
  editVersion: number;
  value: string;
  expectedRevision: number | null;
  mutationKey: string;
}>;

type TransmissionOutcome = "saved" | "conflict" | "error" | "transport" | "busy";

export type AssessmentDraftAutosaveConflict = Readonly<{
  message: string;
  serverDraft: AssessmentDraftConflictSnapshot | null;
}>;

export type AssessmentDraftAutosaveState = Readonly<{
  value: string;
  setValue: (value: string) => void;
  saveStatus: string;
  conflict: AssessmentDraftAutosaveConflict | null;
  useSavedVersion: () => void;
  replaceSavedVersion: () => void;
  flushExactCurrentEdit: () => Promise<boolean>;
  bestEffortCurrentEdit: () => Promise<void>;
}>;

const DEBOUNCE_MS = 500;
const RETRY_MS = 1_500;
export const EMERGENCY_EXIT_TIMEOUT_MS = 900;

function initialEditValue(draft: AssessmentAttemptClientDraft | null): string {
  if (draft?.value === true) return "true";
  if (draft?.value === false) return "false";
  return typeof draft?.value === "string" ? draft.value : "";
}

function draftPayload(
  questionType: AssessmentAttemptClientQuestion["questionType"],
  value: string
): unknown {
  if (questionType === "TRUE_FALSE") {
    if (value === "true") return true;
    if (value === "false") return false;
    return null;
  }
  if (questionType === "MULTIPLE_CHOICE") {
    return value.length === 0 ? null : value;
  }
  return value;
}

function mutationKey(editVersion: number): string {
  return `m208-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}-${editVersion}`;
}

export function useAssessmentDraftAutosave(input: {
  question: AssessmentAttemptClientQuestion;
  initialDraft: AssessmentAttemptClientDraft | null;
}): AssessmentDraftAutosaveState {
  const { question, initialDraft } = input;
  const [value, setValueState] = useState(() => initialEditValue(initialDraft));
  const [saveStatus, setSaveStatus] = useState(initialDraft === null ? "Ready" : "Saved");
  const [conflict, setConflict] = useState<AssessmentDraftAutosaveConflict | null>(null);

  const currentValueRef = useRef(value);
  const revisionRef = useRef<number | null>(initialDraft?.revision ?? null);
  const editVersionRef = useRef(0);
  const acknowledgedEditVersionRef = useRef(initialDraft === null ? -1 : 0);
  const inFlightRef = useRef<SaveRequest | null>(null);
  const idleWaitersRef = useRef<Array<() => void>>([]);
  const retryPendingRef = useRef(false);
  const retryRequestRef = useRef<SaveRequest | null>(null);
  const conflictRef = useRef<AssessmentDraftAutosaveConflict | null>(null);
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const retryTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const mountedRef = useRef(true);
  const sendRequestRef = useRef<(request: SaveRequest) => void>(() => undefined);

  const clearDebounce = useCallback(() => {
    if (debounceTimerRef.current !== null) {
      clearTimeout(debounceTimerRef.current);
      debounceTimerRef.current = null;
    }
  }, []);

  const clearRetry = useCallback(() => {
    if (retryTimerRef.current !== null) {
      clearTimeout(retryTimerRef.current);
      retryTimerRef.current = null;
    }
  }, []);

  const makeRequest = useCallback(
    (
      requestValue: string,
      editVersion: number,
      expectedRevision: number | null = revisionRef.current
    ): SaveRequest =>
      Object.freeze({
        editVersion,
        value: requestValue,
        expectedRevision,
        mutationKey: mutationKey(editVersion)
      }),
    []
  );

  const waitUntilIdle = useCallback(async (): Promise<boolean> => {
    if (inFlightRef.current === null) return mountedRef.current;
    await new Promise<void>((resolve) => {
      idleWaitersRef.current.push(resolve);
    });
    return mountedRef.current;
  }, []);

  const queueLatest = useCallback(
    (delay = DEBOUNCE_MS) => {
      clearDebounce();
      debounceTimerRef.current = setTimeout(() => {
        debounceTimerRef.current = null;
        if (
          !mountedRef.current ||
          inFlightRef.current !== null ||
          retryPendingRef.current ||
          conflictRef.current !== null
        ) {
          return;
        }
        const request = makeRequest(currentValueRef.current, editVersionRef.current);
        sendRequestRef.current(request);
      }, delay);
    },
    [clearDebounce, makeRequest]
  );

  const transmit = useCallback(
    async (request: SaveRequest): Promise<TransmissionOutcome> => {
      if (!mountedRef.current || inFlightRef.current !== null) return "busy";
      inFlightRef.current = request;
      clearRetry();

      const formData = new FormData();
      formData.set("attemptId", question.attemptId);
      formData.set("position", String(question.position));
      formData.set("questionVersionId", question.questionVersionId);
      formData.set("draftPayload", JSON.stringify(draftPayload(question.questionType, request.value)));
      formData.set(
        "expectedRevision",
        request.expectedRevision === null ? "" : String(request.expectedRevision)
      );
      formData.set("clientGeneratedMutationKey", request.mutationKey);

      try {
        const result = await saveAssessmentDraftAction(formData);
        if (!mountedRef.current) return "error";

        if (result.status === "saved") {
          retryPendingRef.current = false;
          retryRequestRef.current = null;
          revisionRef.current = result.revision;
          if (editVersionRef.current === request.editVersion) {
            acknowledgedEditVersionRef.current = request.editVersion;
            setSaveStatus("Saved");
          } else {
            setSaveStatus("Saving…");
          }
          return "saved";
        }

        if (result.status === "conflict") {
          retryPendingRef.current = false;
          retryRequestRef.current = null;
          const nextConflict = Object.freeze({
            message: result.message,
            serverDraft: result.serverDraft
          });
          conflictRef.current = nextConflict;
          setConflict(nextConflict);
          setSaveStatus("Conflict");
          return "conflict";
        }

        retryPendingRef.current = false;
        retryRequestRef.current = null;
        setSaveStatus(result.message);
        return "error";
      } catch {
        if (!mountedRef.current) return "transport";
        retryPendingRef.current = true;
        retryRequestRef.current = request;
        setSaveStatus("Not saved — reconnecting");
        retryTimerRef.current = setTimeout(() => {
          retryTimerRef.current = null;
          if (!mountedRef.current) return;
          retryPendingRef.current = false;
          retryRequestRef.current = null;
          sendRequestRef.current(request);
        }, RETRY_MS);
        return "transport";
      } finally {
        inFlightRef.current = null;
        for (const resolve of idleWaitersRef.current.splice(0)) resolve();
        if (
          mountedRef.current &&
          !retryPendingRef.current &&
          conflictRef.current === null &&
          editVersionRef.current !== request.editVersion
        ) {
          queueLatest(0);
        }
      }
    },
    [clearRetry, queueLatest, question]
  );

  useEffect(() => {
    sendRequestRef.current = (request: SaveRequest) => {
      void transmit(request);
    };
  }, [transmit]);

  const setValue = useCallback(
    (nextValue: string) => {
      currentValueRef.current = nextValue;
      editVersionRef.current += 1;
      conflictRef.current = null;
      setConflict(null);
      setValueState(nextValue);
      setSaveStatus("Saving…");
      queueLatest();
    },
    [queueLatest]
  );

  const useSavedVersion = useCallback(() => {
    const serverDraft = conflictRef.current?.serverDraft;
    if (!serverDraft) return;
    clearDebounce();
    clearRetry();
    retryPendingRef.current = false;
    retryRequestRef.current = null;
    revisionRef.current = serverDraft.revision;
    const savedValue =
      serverDraft.value === true
        ? "true"
        : serverDraft.value === false
          ? "false"
          : typeof serverDraft.value === "string"
            ? serverDraft.value
            : "";
    currentValueRef.current = savedValue;
    editVersionRef.current += 1;
    acknowledgedEditVersionRef.current = editVersionRef.current;
    conflictRef.current = null;
    setConflict(null);
    setValueState(savedValue);
    setSaveStatus("Saved");
  }, [clearDebounce, clearRetry]);

  const replaceSavedVersion = useCallback(() => {
    const serverDraft = conflictRef.current?.serverDraft;
    if (!serverDraft || inFlightRef.current !== null) return;
    clearDebounce();
    clearRetry();
    retryPendingRef.current = false;
    retryRequestRef.current = null;
    revisionRef.current = serverDraft.revision;
    conflictRef.current = null;
    setConflict(null);
    setSaveStatus("Saving…");
    const request = makeRequest(
      currentValueRef.current,
      editVersionRef.current,
      serverDraft.revision
    );
    sendRequestRef.current(request);
  }, [clearDebounce, clearRetry, makeRequest]);

  const flushExactCurrentEdit = useCallback(async (): Promise<boolean> => {
    clearDebounce();

    if (!(await waitUntilIdle()) || conflictRef.current !== null) return false;

    if (retryPendingRef.current && retryRequestRef.current !== null) {
      const retryRequest = retryRequestRef.current;
      clearRetry();
      retryPendingRef.current = false;
      retryRequestRef.current = null;
      const retryOutcome = await transmit(retryRequest);
      if (retryOutcome !== "saved") return false;
      if (!(await waitUntilIdle()) || conflictRef.current !== null) return false;
    }

    const targetEditVersion = editVersionRef.current;
    if (acknowledgedEditVersionRef.current === targetEditVersion) return true;

    setSaveStatus("Saving…");
    const request = makeRequest(currentValueRef.current, targetEditVersion);
    const outcome = await transmit(request);
    if (outcome !== "saved") return false;
    if (editVersionRef.current !== targetEditVersion) return false;
    if (acknowledgedEditVersionRef.current !== targetEditVersion) return false;
    return true;
  }, [clearDebounce, clearRetry, makeRequest, transmit, waitUntilIdle]);

  const bestEffortCurrentEdit = useCallback(async (): Promise<void> => {
    await Promise.race([
      flushExactCurrentEdit(),
      new Promise<boolean>((resolve) => {
        setTimeout(() => resolve(false), EMERGENCY_EXIT_TIMEOUT_MS);
      })
    ]);
  }, [flushExactCurrentEdit]);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
      clearDebounce();
      clearRetry();
      for (const resolve of idleWaitersRef.current.splice(0)) resolve();
    };
  }, [clearDebounce, clearRetry]);

  return {
    value,
    setValue,
    saveStatus,
    conflict,
    useSavedVersion,
    replaceSavedVersion,
    flushExactCurrentEdit,
    bestEffortCurrentEdit
  };
}

