  const down = await source("database/migrations/0044_assessment_interruption_recovery.down.sql");
  const domain = await source("src/lib/assessment-attempt/assessment-attempt-domain.ts");
  const service = await source("src/lib/assessment-attempt/assessment-attempt-service.ts");

  assert.ok(up.trim(), "0044_assessment_interruption_recovery.up.sql is missing");
  assert.ok(down.trim(), "0044_assessment_interruption_recovery.down.sql is missing");
  for (const status of ["INTERRUPTED", "REVIEW_REQUIRED", "INVALIDATED", "REPLACED"]) {
    assert.match(domain, new RegExp(`\\"${status}\\"`));
    assert.match(up, new RegExp(status));
  }
  assert.match(up, /assessment_attempt_session_bindings/i);
  assert.match(up, /assessment_attempt_exposures/i);
  assert.match(up, /assessment_attempt_interruptions/i);
  assert.match(up, /auth_session_id/i);
  assert.match(up, /security_context_digest/i);
  assert.match(up, /released_at/i);
  assert.match(up, /replacement_attempt_id/i);
  assert.match(up, /replacement_form_id/i);
  assert.match(up, /original_form_id/i);
  assert.match(up, /question_version_id/i);
  assert.match(up, /reason_code/i);
  assert.match(up, /revision/i);
  assert.match(service, /assertAndBindAttemptSession/);
  assert.match(service, /recordCurrentQuestionExposure/);
  assert.match(service, /interrupt/);
  assert.match(service, /resumeInterrupted/);
});

