    });
    const first = await service.saveCurrentDraft(principal, firstInput, ATTEMPT_NOW_DATE);
    assert.equal(first.revision, 1);
    const retry = await service.saveCurrentDraft(principal, firstInput, ATTEMPT_NOW_DATE);
